declare function local:run-emiss-factors($scenarios as xs:string*, $regions as xs:string*, $collection as xs:string) as node()* {
    unordered {
        let $regionsG := if(not($regions[1] = 'Global'))
            then $regions
            else distinct-values(collection($collection)/scenario/world/*[@type='region']/@name)
        return
        for $scenario in $scenarios,
            $region in $regionsG
        let $scenario_split := tokenize($scenario, ' '),
            $scenario_name  := string-join($scenario_split[position() < last()], ' '),
            $scenario_date  := $scenario_split[last()],
            $currTree := collection($collection)/scenario[@name = $scenario_name and @date = $scenario_date]/world/*[@type = 'region' and @name=$region]
        for $sector in $currTree/*[@type='sector']
        for $subsector in $sector/*[@type='subsector']
        let $techs := $subsector//*[@type='technology']
        for $ghg_name in distinct-values($techs/*[@type='GHG']/@name)
        where $ghg_name = ('CO2', 'NOx', 'SO2', 'PM2.5', 'PM10', 'CO', 'NH3')
        let $all_ghg := $techs/*[@type='GHG' and @name=$ghg_name]
        let $all_outputs := $techs/output-primary[@type='output']/physical-output
        for $year in distinct-values($all_ghg/emissions/@year)
        let $total_emiss  := sum($all_ghg/emissions[@year=$year])
        let $total_output := sum($all_outputs[@vintage=$year])
        let $emiss_unit   := string(($all_ghg/emissions[@year=$year]/@unit)[1])
        let $output_unit  := string(($all_outputs[@vintage=$year]/@unit)[1])
        where $total_output > 0 and $total_emiss != 0
        return local:append-heirarchy($currTree,
            element { local-name($sector) } { $sector/@*,
                element { local-name($subsector) } { $subsector/@*,
                    element GHG {
                        attribute name { $ghg_name },
                        attribute type { 'GHG' },
                        element emissions {
                            attribute year { $year },
                            attribute unit { concat($emiss_unit, '/', $output_unit) },
                            text { $total_emiss div $total_output }
                        }
                    }
                }
            }
        )//text()
    }
};
local:run-emiss-factors((:scenarios:), (:regions:), (:collection:))

