local:run-sales-share-sector((:scenarios:), (:regions:), (:collection:))

        (
        let $rgn := .
		for $sub in $rgn//*[@type='subsector' and ancestor::*[starts-with(@name, 'trn')]]
		(: Strict sales/model-year points are technology installation years :)
		let $model_years := distinct-values($sub/*[@type='technology']/@year)
		for $y in $model_years
        
		let $tech_nodes := $sub/*[@type='technology' and @year=$y],
			$out_nodes := $tech_nodes/*:output-primary[@type='output']/*:physical-output[@vintage=$y],
            $service_raw := sum($out_nodes),
			$fuel_ej := sum($tech_nodes//*:input-energy[not(starts-with(@name, 'water_td'))]/*:demand-physical[@vintage=$y]),
            
            (: DYNAMIC UNIT SCALING: Adjust for Billion vs Million service-km :)
            $unit_label := lower-case(string(($out_nodes/@unit)[1])),
            $multiplier := if (contains($unit_label, 'billion')) then 1000000000 
                           else 1000000, 
            
			(: Prefer load factors from this model-year cohort; fallback to subsector average :)
			$load_nodes := $tech_nodes//load-factor[@year=$y or @vintage=$y],
            $applied_load := if (exists($load_nodes)) then avg($load_nodes) 
							 else if (exists($tech_nodes//load-factor))
							 then avg($tech_nodes//load-factor)
                             else if (exists($sub/*[@type='technology']//load-factor)) 
                             then avg($sub/*[@type='technology']//load-factor)
                             else 1.0,
            
(: CONVERSION LOGIC :)
$service_total_km := $service_raw * $multiplier,
$service_vmt := ($service_total_km div $applied_load) div 1.60934,

(: fuel_ej is in EJ; 1 EJ = 1,000,000,000 GJ. :)
(: We use 0.1213 GJ/gal as the gasoline LHV equivalent :)
$gallons := ($fuel_ej * 1000000000) div 0.1213,

(: MATH: VMT / Gallons :)
$vehicle_mpg := if ($gallons > 0 and $service_vmt > 0) 
                then round(($service_vmt div $gallons) * 100) div 100 
                else 0
        
        where $vehicle_mpg > 0
        
        return document { 
            element scenario {
                $rgn/ancestor::scenario/@*,
                element region {
                    $rgn/@*,
                    element sector {
                        attribute name { string($sub/parent::*/@name) },
                        element subsector {
                            attribute name { string($sub/@name) },
                            element mpg {
                                attribute year { string($y) },
                                attribute unit { "VMT/GGE" },
                                (: Verification attributes :)
                                attribute load_used { $applied_load },
                                attribute scale_used { $multiplier },
                                text { $vehicle_mpg }
                            }
                        }
                    }
                }
            }
        }
        )//text()

        (
        let $rgn := .
        for $sub in $rgn//*[@type='subsector' and ancestor::*[starts-with(@name, 'trn')]]
        let $all_years := distinct-values($sub/*[@type='technology']/*:output-primary[@type='output']/*:physical-output/@vintage)
        for $y in $all_years

        let $out_nodes := $sub/*[@type='technology']/*:output-primary[@type='output']/*:physical-output[@vintage=$y],
            $service_raw := sum($out_nodes),
            $fuel_ej := sum($sub/*[@type='technology']//*:input-energy[not(starts-with(@name, 'water_td'))]/*:demand-physical[@vintage=$y]),

            $unit_label := lower-case(string(($out_nodes/@unit)[1])),
            $multiplier := if (contains($unit_label, 'billion')) then 1000000000 else 1000000,

            $load_nodes := $sub/*[@type='technology']//load-factor[@year=$y or @vintage=$y],
            $applied_load := if (exists($load_nodes)) then avg($load_nodes)
                             else if (exists($sub/*[@type='technology']//load-factor)) then avg($sub/*[@type='technology']//load-factor)
                             else 1.0,

            (: CONVERSION LOGIC :)
            $service_vmt := (($service_raw * $multiplier) div $applied_load) div 1.60934,
            $gallons := ($fuel_ej * 1000000000) div 0.1213,
            
            $vehicle_mpg := if ($gallons > 0 and $service_vmt > 0)
                            then round(($service_vmt div $gallons) * 100) div 100
                            else 0

        where $vehicle_mpg > 0

        return document {
            element scenario {
                $rgn/ancestor::scenario/@*,
                element region {
                    $rgn/@*,
                    element sector {
                        attribute name { string($sub/parent::*/@name) },
                        element subsector {
                            attribute name { string($sub/@name) },
                            element mpg {
                                attribute year { string($y) },
                                attribute unit { "VMT/GGE" },
                                text { $vehicle_mpg }
                            }
                        }
                    }
                }
            }
        }
        )//text()

(
let $rgn := .
for $sub in $rgn//*[@type='subsector' and ancestor::*[starts-with(@name, 'trn')]]
(: Sales/model-year points are technology installation years :)
let $model_years := distinct-values($sub/*[@type='technology']/@year)
for $y in $model_years

let $tech_nodes := $sub/*[@type='technology' and @year=$y],
    $out_nodes := $tech_nodes/*:output-primary[@type='output']/*:physical-output[@vintage=$y],
    $service_raw := sum($out_nodes),
    $fuel_ej := sum($tech_nodes//*:input-energy[not(starts-with(@name, 'water_td'))]/*:demand-physical[@vintage=$y]),
    
    (: Unit Detection :)
    $unit_label := lower-case(string(($out_nodes/@unit)[1])),
    $multiplier := if (contains($unit_label, 'billion')) then 1000000000 
                   else 1000000, 
    
    (: CONVERSION LOGIC :)
    (: Convert total passenger-km to passenger-miles (PMT) :)
    $total_service_pmt := ($service_raw * $multiplier) div 1.60934,
    
    (: Convert EJ to Gallons (GGE) using 0.1213 GJ/gal :)
    $gallons := ($fuel_ej * 1000000000) div 0.1213,
    
    (: MATH: PMT / Gallons :)
    $vehicle_mpg := if ($gallons > 0 and $total_service_pmt > 0) 
                    then round(($total_service_pmt div $gallons) * 100) div 100 
                    else 0

where $vehicle_mpg > 0

return document { 
    element scenario {
        $rgn/ancestor::scenario/@*,
        element region {
            $rgn/@*,
            element sector {
                attribute name { string($sub/parent::*/@name) },
                element subsector {
                    attribute name { string($sub/@name) },
                    element mpg {
                        attribute year { string($y) },
                        attribute unit { "PMT/GGE" },
                        (: Diagnostic Attributes :)
                        attribute detected_unit { $unit_label },
                        text { $vehicle_mpg }
                    }
                }
            }
        }
    }
}
)//text()

declare function local:append-heirarchy($parent as node(), $append as node()*) as node() {
    let $scn := $parent/ancestor::scenario,
        $rgn := $parent
    return
        document { element scenario {
            $scn/@*,
            element region {
                $rgn/@*,
                $append
            }
        }}
};
declare function local:run-transport-mpg-load($scenarios as xs:string*, $regions as xs:string*, $collection as xs:string) as node()* {
    unordered {
    let $regionsG := if(not($regions[1] = 'Global'))
        then $regions
        else distinct-values(collection($collection)/scenario/world/*[@type='region']/@name)
    return
    for $scenario in $scenarios,
        $region in $regionsG
    let $scenario_split := tokenize($scenario, ' '),
        $scenario_name  := string-join($scenario_split[position() < last()], ' '),
        $scenario_date  := $scenario_split[last()],
        $currTree := collection($collection)/scenario[@name = $scenario_name and @date = $scenario_date]/world/*[@type = 'region' and @name=$region]
    
    for $sector in $currTree/*[@type='sector' and starts-with(@name, 'trn')]
    for $subsector in $sector/*[@type='subsector']
    for $tech_name in distinct-values($subsector//*[@type='technology']/@name)
    let $tech_vintages := $subsector//*[@type='technology' and @name=$tech_name]
    let $all_inputs := $tech_vintages/input-energy[not(starts-with(@name, 'water_td'))]
    
    (: Extract load factor: tech level, fallback to subsector :)
    let $load_node := ($tech_vintages//load-factor | $subsector/load-factor)[1]
    let $load_val  := if (exists($load_node)) then number($load_node) else 1.0
    
    for $year in distinct-values($tech_vintages/output-primary[@type='output']/physical-output/@vintage)
    let $total_input  := sum($all_inputs/demand-physical[@vintage=$year])
    let $total_output := sum($tech_vintages/output-primary[@type='output']/physical-output[@vintage=$year])
    
    let $output_unit  := string(($tech_vintages/output-primary[@type='output']/physical-output[@vintage=$year]/@unit)[1])
    (: Adjust multiplier if units are Million instead of Billion :)
    let $unit_scaling := if (contains(lower-case($output_unit), 'million')) then 0.001 else 1.0
    
    (: MPGe Conversion Math :)
    (: 1. (Billion pass-km / EJ) / Load Factor = Billion vehicle-km / EJ :)
    (: 2. Convert km to miles: div 1.60934 :)
    (: 3. Convert EJ to Gallons: (EJ * 10^9) / 0.1213 :)
    (: Simplified Factor: (1 / 1.60934) * (0.1213 / 1) = 0.0753... but with unit powers: :)
    
    let $v_km_per_ej := if ($total_input > 0) then ($total_output * $unit_scaling) div $total_input div $load_val else 0
    let $mpg_equiv   := ($v_km_per_ej div 1.60934) * (0.1213 div 1.0)
    
    where $total_output > 0 and $total_input > 0
    return local:append-heirarchy($currTree,
        element { local-name($sector) } { $sector/@*,
            element { local-name($subsector) } { $subsector/@*,
                element technology {
                    attribute name { $tech_name },
                    attribute type { 'technology' },
                    element input {
                        attribute name { 'MPGe' },
                        attribute type { 'input' },
                        element demand-physical {
                            attribute vintage { $year },
                            attribute unit { 'MPGe' },
                            text { round($mpg_equiv * 100) div 100 }
                        }
                    }
                }
            }
        }
    )//text()
    }
};
local:run-transport-mpg-load((:scenarios:), (:regions:), (:collection:))
